        Dictionary<string, object> dictionary = (Dictionary<string, object>)javaScriptExecutor.ExecuteScript("\r\n        const rect = arguments[0].getBoundingClientRect();\r\n        const dpr = window.devicePixelRatio || 1;\r\n\r\n        const viewportOffsetY = window.visualViewport\r\n            ? window.visualViewport.offsetTop\r\n            : 0;\r\n\r\n        return {\r\n            screenX: window.screenX,\r\n            screenY: window.screenY,\r\n            x: (rect.left + rect.width / 2) * dpr,\r\n            y: (rect.top + rect.height / 2 + viewportOffsetY) * dpr\r\n        };\r\n    ", element);
