    internal void StartChromeNetworkCapture()
    {
        try
        {
            HttpClient client = new HttpClient();

            string json = client.GetStringAsync("http://localhost:9222/json")
                                .GetAwaiter()
                                .GetResult();

            JArray tabs = JArray.Parse(json);

            string wsUrl = "";

            foreach (JObject tab in tabs)
            {
                if (tab["type"] != null &&
                    tab["type"].ToString() == "page" &&
                    tab["webSocketDebuggerUrl"] != null)
                {
                    wsUrl = tab["webSocketDebuggerUrl"].ToString();
                    break;
                }
            }

            if (string.IsNullOrWhiteSpace(wsUrl))
                return;

            ws = new WebsocketClient(new Uri(wsUrl));

            ws.MessageReceived.Subscribe(msg =>
            {
                ReadChromeResponse(msg.Text);
            });

            ws.Start().GetAwaiter().GetResult();

            ws.Send("{\"id\":1,\"method\":\"Network.enable\"}");
        }
        catch
        {
        }
    }
    internal void ReadChromeResponse(string text)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(text))
                return;

            JObject data = JObject.Parse(text);

            // ==========================
            // REQUEST
            // ==========================
            if (data["method"] != null &&
                data["method"].ToString() == "Network.requestWillBeSent")
            {
                string reqUrl =
                    data["params"]["request"]["url"].ToString();

                string reqMethod =
                    data["params"]["request"]["method"].ToString();

                Console.WriteLine("===== REQUEST =====");
                Console.WriteLine("METHOD : " + reqMethod);
                Console.WriteLine("URL    : " + reqUrl);
            }
            if (data["method"] != null && data["method"].ToString() == "Network.responseReceived")
            {
                string requestId =
                    data["params"]["requestId"].ToString();

                string resUrl =
                    data["params"]["response"]["url"].ToString();

                string status =
                    data["params"]["response"]["status"].ToString();

                Console.WriteLine("===== RESPONSE =====");
                Console.WriteLine("URL    : " + resUrl);
                Console.WriteLine("STATUS : " + status);
                ws.Send("{\"id\":99,\"method\":\"Network.getResponseBody\",\"params\":{\"requestId\":\"" + requestId + "\"}}");
            }
            if (data["id"] != null && data["id"].ToString() == "99")
            {
                if (data["result"] != null && data["result"]["body"] != null)
                {
                    string body = data["result"]["body"].ToString();
                }
            }
        }
        catch
        {
        }
    }
    public void ClickSearchButton(UndetectedChromeDriver driver)
    {
        HumanMouseClicker humanMouseClicker = new HumanMouseClicker();
        string cssSelectorToFind = "button.search_btn.train_Search[type='submit']";
        humanMouseClicker.RealHumanClick(driver, By.CssSelector(cssSelectorToFind));
    }
    public void ClickSearchButtonEdge(IWebDriver driver)
    {
        HumanMouseClicker humanMouseClicker = new HumanMouseClicker();
        string cssSelectorToFind = "button.search_btn.train_Search[type='submit']";
        humanMouseClicker.RealHumanClickEDGE(driver, By.CssSelector(cssSelectorToFind));
    }

    public void ClickSearchButtonEdge(IPage page)
    {
        string cssSelector = "button.search_btn.train_Search[type='submit']";

        page.WaitForSelectorAsync(cssSelector).GetAwaiter().GetResult();
        page.ClickAsync(cssSelector).GetAwaiter().GetResult();
    }
    internal string ClassCodeToText(string code)
    {
        code = code.ToUpperInvariant().Trim();
        string result = "";
        switch (code)
        {
            case "2S":
                result = "Second Sitting (2S)";
                break;
            case "CC":
                result = "AC Chair Car (CC)";
                break;
            case "2A":
                result = "AC 2 Tier (2A)";
                break;
            case "3A":
                result = "AC 3 Tier (3A)";
                break;
            case "SL":
                result = "Sleeper (SL)";
                break;
        }
        return result;
    }
