        string text2 = "\r\n        async (args) => {\r\n            try {\r\n                // args.headers automatically C# Dictionary se JS object ban chuka hai\r\n                const response = await fetch(args.url, {\r\n                    method: 'POST', \r\n                    headers: args.headers, // Yahan aapke saare headers apply ho jayenge\r\n                    body: args.payload\r\n                });\r\n                \r\n                const status = response.status;\r\n                const responseText = await response.text();\r\n                \r\n                // Result ko C# mein wapas bhej rahe hain\r\n                return JSON.stringify({ \r\n                    success: response.ok, \r\n                    status: status, \r\n                    data: responseText \r\n                });\r\n            } catch (error) {\r\n                return JSON.stringify({ \r\n                    success: false, \r\n                    status: 500, \r\n                    error: error.message || 'Network error in JS fetch' \r\n                });\r\n            }\r\n        }";
