    private static readonly string FetchScriptGet = @"
async (args) => {
    try {

        const resp = await fetch(args.url, {
            method: 'GET',
            headers: args.headers,
            credentials: 'include',
            cache: 'no-cache'
        });

        const text = await resp.text();

        const headersReceived = {};
        resp.headers.forEach((value, key) => {
            headersReceived[key] = value;
        });

        return JSON.stringify({
            success: true,
            status: resp.status,
            body: text,
            headers: headersReceived
        });

    } catch (e) {

        return JSON.stringify({
            success: false,
            error: e.message || e.toString()
        });

    }
}";
    private bool GetUsingPlayWriteHistory(IPage page, string url, string referer, ref string response)
    {
        response = "";

        var headers = new Dictionary<string, string>
        {
            ["Accept"] = "application/json, text/plain, */*",
            ["Accept-Language"] = "en-US,en;q=0.9",
            ["Authorization"] = _Authrization,
            ["bmirak"] = bmirak,
            ["bmiyek"] = bmiyek,
            ["Content-Language"] = "en",
            ["greq"] = greq,
            ["spa-csrf-token"] = csrf_token
        };

        if (!string.IsNullOrWhiteSpace(referer))
            headers["Referer"] = referer;

        for (int retry = 0; retry < 3; retry++)
        {
            try
            {
                string jsonText = page
                    .EvaluateAsync<string>(
                        FetchScriptGet,
                        new
                        {
                            url,
                            headers
                        })
                    .GetAwaiter()
                    .GetResult();

                if (string.IsNullOrWhiteSpace(jsonText))
                {
                    Thread.Sleep(150);
                    continue;
                }

                JObject json;

                try
                {
                    json = JObject.Parse(jsonText);
                }
                catch
                {
                    Thread.Sleep(150);
                    continue;
                }

                if (!(json.Value<bool?>("success") ?? false))
                {
                    if (retry < 2)
                    {
                        Thread.Sleep(150);
                        continue;
                    }

                    return false;
                }

                response = json.Value<string>("body") ?? "";

                if (json["headers"] is JObject hdr)
                {
                    csrf_token =
                        hdr.Value<string>("spa-csrf-token")
                        ?? hdr.Value<string>("csrf-token")
                        ?? csrf_token;
                }

                int status = json.Value<int?>("status") ?? 0;

                if (status == 401 || status == 403)
                    return false;

                return status >= 200 && status < 300;
            }
            catch (Exception ex)
            {
                errorLog_R(url, "", ex.ToString());

                if (retry == 2)
                    Console.WriteLine(ex);

                Thread.Sleep(150);
            }
        }

        return false;
    }
