    private string ToBase36(long value)
    {
        if (value == 0L)
        {
            return "0";
        }
        string text = "";
        while (value > 0L)
        {
            int index = (int)(value % 36L);
            text = Base36Chars[index] + text;
            value /= 36L;
        }
        return text;
    }

