    private static string GenerateRandomString(int length)
    {
        if (length <= 0)
            return string.Empty;

        const string chars =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

        char[] result = new char[length];

        using (var rng = System.Security.Cryptography.RandomNumberGenerator.Create())
        {
            byte[] buffer = new byte[length];

            rng.GetBytes(buffer);

            for (int i = 0; i < length; i++)
            {
                result[i] = chars[buffer[i] % chars.Length];
            }
        }

        return new string(result);
    }
    private bool IsAdministrator()
    {
        using (System.Security.Principal.WindowsIdentity identity =
               System.Security.Principal.WindowsIdentity.GetCurrent())
        {
            System.Security.Principal.WindowsPrincipal principal =
                new System.Security.Principal.WindowsPrincipal(identity);

            return principal.IsInRole(
                System.Security.Principal.WindowsBuiltInRole.Administrator
            );
        }
    }
    private void SetRegistryValue(RegistryHive hive, string subKey, string valueName, object value, RegistryValueKind valueKind)
    {
        using (RegistryKey baseKey = RegistryKey.OpenBaseKey(hive, RegistryView.Registry64))
        {
            using (RegistryKey key =
                   baseKey.CreateSubKey(subKey))
            {
                if (key == null)
                {
                    throw new Exception(
                        "Registry key create/open नहीं हो सकी:\n" + subKey);
                }

                key.SetValue(
                    valueName,
                    value,
                    valueKind
                );
            }
        }
    }
    private void ConfigureService(string serviceName, string startType)
    {
        RunCommand(
            "sc.exe",
            $"config \"{serviceName}\" start= {startType}"
        );
    }
    private bool RunPowerShell(string command)
    {
        try
        {
            using (Process process = new Process())
            {
                process.StartInfo = new ProcessStartInfo
                {
                    FileName = "powershell.exe",
                    Arguments =
                        "-NoProfile -NonInteractive -ExecutionPolicy Bypass " +
                        "-Command \"" + command.Replace("\"", "\\\"") + "\"",

                    UseShellExecute = false,
                    CreateNoWindow = true,
                    WindowStyle = ProcessWindowStyle.Hidden,

                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };

                process.Start();

                string output =
                    process.StandardOutput.ReadToEnd();

                string error =
                    process.StandardError.ReadToEnd();

                process.WaitForExit();

                return process.ExitCode == 0;
            }
        }
        catch
        {
            return false;
        }
    }
    private bool StopService(string serviceName)
    {
        try
        {
            using (ServiceController service =
                   new ServiceController(serviceName))
            {
                // Service already stopped
                if (service.Status == ServiceControllerStatus.Stopped)
                {
                    return true;
                }

                // Stop service
                if (service.Status == ServiceControllerStatus.Running ||
                    service.Status == ServiceControllerStatus.Paused)
                {
                    service.Stop();

                    service.WaitForStatus(
                        ServiceControllerStatus.Stopped,
                        TimeSpan.FromSeconds(15)
                    );

                    return service.Status ==
                           ServiceControllerStatus.Stopped;
                }

                // If service is stopping, wait for it
                if (service.Status == ServiceControllerStatus.StopPending)
                {
                    service.WaitForStatus(
                        ServiceControllerStatus.Stopped,
                        TimeSpan.FromSeconds(15)
                    );

                    return service.Status ==
                           ServiceControllerStatus.Stopped;
                }

                return false;
            }
        }
        catch (InvalidOperationException)
        {
            return false;
        }
        catch (System.ComponentModel.Win32Exception)
        {
            return false;
        }
        catch
        {
            return false;
        }
    }
    private bool RunCommand(string fileName, string arguments)
    {
        try
        {
            using (Process process = new Process())
            {
                process.StartInfo = new ProcessStartInfo
                {
                    FileName = fileName,
                    Arguments = arguments,
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    WindowStyle = ProcessWindowStyle.Hidden,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true
                };

                process.Start();

                // Output/error को read करें ताकि process properly complete हो
                string output = process.StandardOutput.ReadToEnd();
                string error = process.StandardError.ReadToEnd();

                process.WaitForExit();

                return process.ExitCode == 0;
            }
        }
        catch
        {
            return false;
        }
    }
    private bool StartService(string serviceName)
    {
        try
        {
            using (ServiceController service =
                   new ServiceController(serviceName))
            {
                // Service already running
                if (service.Status == ServiceControllerStatus.Running)
                {
                    return true;
                }

                // Start only when stopped
                if (service.Status == ServiceControllerStatus.Stopped ||
                    service.Status == ServiceControllerStatus.Paused)
                {
                    service.Start();

                    service.WaitForStatus(
                        ServiceControllerStatus.Running,
                        TimeSpan.FromSeconds(15)
                    );

                    return service.Status ==
                           ServiceControllerStatus.Running;
                }

                // If service is starting, wait for it
                if (service.Status == ServiceControllerStatus.StartPending)
                {
                    service.WaitForStatus(
                        ServiceControllerStatus.Running,
                        TimeSpan.FromSeconds(15)
                    );

                    return service.Status ==
                           ServiceControllerStatus.Running;
                }

                return false;
            }
        }
        catch (InvalidOperationException)
        {
            return false;
        }
        catch (System.ComponentModel.Win32Exception)
        {
            return false;
        }
        catch
        {
            return false;
        }
    }
    private void EnableLocationAndIPv6()
    {
        try
        {
            if (!IsAdministrator())
            {
                MessageBox.Show(
                    "Administrator permission required.\n\n" +
                    "Please run the application as Administrator.",
                    "Administrator Required",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning
                );

                return;
            }
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors",
                "DisableLocation",
                0,
                RegistryValueKind.DWord
            );
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors",
                "DisableSensors",
                0,
                RegistryValueKind.DWord
            );

            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors",
                "DisableLocationScripting",
                0,
                RegistryValueKind.DWord
            );
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy",
                "LetAppsAccessLocation",
                0,
                RegistryValueKind.DWord
            );

            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location",
                "Value",
                "Allow",
                RegistryValueKind.String
            );
            SetRegistryValue(
                RegistryHive.CurrentUser,
                @"SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location",
                "Value",
                "Allow",
                RegistryValueKind.String
            );
            ConfigureService("lfsvc", "auto");
            StartService("lfsvc");

            ConfigureService("SensorService", "demand");
            StartService("SensorService");

            ConfigureService("SensrSvc", "demand");
            StartService("SensrSvc");

            ConfigureService("SensorDataService", "demand");
            StartService("SensorDataService");
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters",
                "DisabledComponents",
                0,
                RegistryValueKind.DWord
            );
            RunCommand(
                "netsh",
                "interface teredo set state default"
            );
            RunCommand(
                "netsh",
                "interface ipv6 6to4 set state default"
            );
            RunCommand(
                "netsh",
                "interface ipv6 isatap set state default"
            );
            string psCommand =
                "Get-NetAdapterBinding -ComponentID ms_tcpip6 " +
                "-ErrorAction SilentlyContinue | " +
                "Where-Object {$_.Enabled -eq $false} | " +
                "Enable-NetAdapterBinding " +
                "-ComponentID ms_tcpip6 " +
                "-Confirm:$false " +
                "-ErrorAction SilentlyContinue";

            RunPowerShell(psCommand);
            RunCommand(
                "ipconfig",
                "/flushdns"
            );
            string path = Path.Combine(Application.StartupPath, "setting.dll");
            if (File.Exists(path))
            {
                File.Delete(path);
            }
            File.WriteAllText(path, "OK");
            Process.Start(new ProcessStartInfo
            {
                FileName = "shutdown.exe",
                Arguments = "/r /t 0",
                UseShellExecute = true,
                Verb = "runas"
            });
        }
        catch (Exception ex)
        {

        }
    }
    private void DisableLocationAndIPv6()
    {
        try
        {
            if (!IsAdministrator())
            {
                MessageBox.Show(
                    "Administrator permission is required.\n\n" +
                    "Please run the application as Administrator.",
                    "Administrator Required",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning
                );

                return;
            }
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors",
                "DisableLocation",
                1,
                RegistryValueKind.DWord
            );

            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors",
                "DisableSensors",
                1,
                RegistryValueKind.DWord
            );

            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\LocationAndSensors",
                "DisableLocationScripting",
                1,
                RegistryValueKind.DWord
            );
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Policies\Microsoft\Windows\AppPrivacy",
                "LetAppsAccessLocation",
                2,
                RegistryValueKind.DWord
            );
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location",
                "Value",
                "Deny",
                RegistryValueKind.String
            );
            SetRegistryValue(
                RegistryHive.CurrentUser,
                @"SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location",
                "Value",
                "Deny",
                RegistryValueKind.String
            );
            StopService("lfsvc");
            ConfigureService("lfsvc", "disabled");

            StopService("SensorService");
            ConfigureService("SensorService", "disabled");

            StopService("SensrSvc");
            ConfigureService("SensrSvc", "disabled");

            StopService("SensorDataService");
            ConfigureService("SensorDataService", "disabled");
            SetRegistryValue(
                RegistryHive.LocalMachine,
                @"SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters",
                "DisabledComponents",
                255,
                RegistryValueKind.DWord
            );
            RunCommand(
                "netsh.exe",
                "interface teredo set state disabled"
            );

            RunCommand(
                "netsh.exe",
                "interface ipv6 6to4 set state disabled"
            );

            RunCommand(
                "netsh.exe",
                "interface ipv6 isatap set state disabled"
            );
            string psCommand =
                "Get-NetAdapterBinding " +
                "-ComponentID ms_tcpip6 " +
                "-ErrorAction SilentlyContinue | " +
                "Where-Object {$_.Enabled} | " +
                "Disable-NetAdapterBinding " +
                "-ComponentID ms_tcpip6 " +
                "-Confirm:$false " +
                "-ErrorAction SilentlyContinue";

            RunPowerShell(psCommand);
            RunCommand(
                "ipconfig.exe",
                "/flushdns"
            );
            string path = Path.Combine(Application.StartupPath, "setting.dll");
            if (File.Exists(path))
            {
                File.Delete(path);
            }
            File.WriteAllText(path, "Disabled");
            Process.Start(new ProcessStartInfo
            {
                FileName = "shutdown.exe",
                Arguments = "/r /t 0",
                UseShellExecute = true,
                Verb = "runas"
            });
        }
        catch (Exception ex)
        {
        }
    }
