    public string ConvertCookieContainerToHeaderString(CookieContainer cookieContainer, string domain)
    {
        string uriString = "https://www.irctc.co.in/";
        ContainsAbckCookie(cookieContainer, new Uri(uriString));
        StringBuilder stringBuilder = new StringBuilder();
        string text = "https://";
        foreach (System.Net.Cookie cookie in cookieContainer.GetCookies(new Uri(text + domain)))
        {
            if (stringBuilder.Length > 0)
            {
                string value = "; ";
                stringBuilder.Append(value);
            }
            string name = cookie.Name;
            string text2 = "=";
            stringBuilder.Append(name + text2 + cookie.Value);
        }
        return stringBuilder.ToString();
    }

    private static bool ContainsAbckCookie(CookieContainer cookieContainer, Uri uri)
    {
        foreach (System.Net.Cookie cookie in cookieContainer.GetCookies(uri))
        {
            string name = cookie.Name;
            string value = "_abck";
            if (name.Equals(value, StringComparison.OrdinalIgnoreCase))
            {
                string text = "Found _abck cookie with value: ";
                Console.WriteLine(text + cookie.Value);
                return true;
            }
        }
        return false;
    }

    public string ReplaceAbckInCookieString(string originalCookieString, string newAbckValue)
    {
        List<string> list = (from part in originalCookieString.Split(';')
                             select part.Trim()).Where(delegate (string part)
                         {
                             string value = "_abck=";
                             return !part.StartsWith(value, StringComparison.OrdinalIgnoreCase);
                         }).ToList();
        string text = "_abck=";
        list.Add(text + newAbckValue);
        string separator = "; ";
        return string.Join(separator, list);
    }

